/* AIVIC_FUNCTION_BUNDLE_START owner=classifyUserSegment exports=classifyUserSegment */
const __aivicBundle_17_classifyUserSegment = (() => {
  function classifyUserSegment(input: {
    age_group: string;
    family_structure: string;
    food_restriction_type: string;
    user_id: string;
  }): string {
    const { age_group, family_structure, food_restriction_type } = input;
  
    // セグメント定義マッピング
    const segmentRules: Array<{
      ageGroup: string;
      familyStructure: string;
      foodRestrictionType: string;
      segmentId: string;
    }> = [
      {
        ageGroup: "30s",
        familyStructure: "couple_with_children",
        foodRestrictionType: "allergy",
        segmentId: "segment_young_family_with_restrictions",
      },
    ];
  
    // 入力条件に合致するセグメントを検索
    const matchedSegment = segmentRules.find(
      (rule) =>
        rule.ageGroup === age_group &&
        rule.familyStructure === family_structure &&
        rule.foodRestrictionType === food_restriction_type
    );
  
    if (!matchedSegment) {
      throw new Error("セグメント条件に合致するセグメントが見つかりません");
    }
  
    return matchedSegment.segmentId;
  }
  return { classifyUserSegment };
})();
export const classifyUserSegment = __aivicBundle_17_classifyUserSegment.classifyUserSegment;
