const __aivicBundle_20_compareAlgorithmImprovementQuantitatively = (() => {
  function compareAlgorithmImprovementQuantitatively(input: {
    beforeAlgorithmDataSet: Array<{
      mealGenerationId: string;
      timestamp: Date;
      satisfactionScore: number;
      completionRate: number;
      rejectionRate: number;
      cookingTimeMinutes: number;
      algorithmVersion: string;
    }>;
    afterAlgorithmDataSet: Array<{
      mealGenerationId: string;
      timestamp: Date;
      satisfactionScore: number;
      completionRate: number;
      rejectionRate: number;
      cookingTimeMinutes: number;
      algorithmVersion: string;
    }>;
    beforePeriodStartDate: Date;
    beforePeriodEndDate: Date;
    afterPeriodStartDate: Date;
    afterPeriodEndDate: Date;
    minimumDataRequirementDays: number;
  }): ComparisonResult {
    const beforeStart = new Date(input.beforePeriodStartDate);
    const beforeEnd = new Date(input.beforePeriodEndDate);
    const afterStart = new Date(input.afterPeriodStartDate);
    const afterEnd = new Date(input.afterPeriodEndDate);
  
    const beforeDaysDiff = Math.floor(
      (beforeEnd.getTime() - beforeStart.getTime()) / (1000 * 60 * 60 * 24)
    );
    const afterDaysDiff = Math.floor(
      (afterEnd.getTime() - afterStart.getTime()) / (1000 * 60 * 60 * 24)
    );
  
    const dataCollectionDaysBefore = beforeDaysDiff;
    const dataCollectionDaysAfter = afterDaysDiff;
  
    if (
      dataCollectionDaysBefore < input.minimumDataRequirementDays ||
      dataCollectionDaysAfter < input.minimumDataRequirementDays
    ) {
      return {
        isAggregatable: false,
        errorMessage: `データ期間が不足しています。${input.minimumDataRequirementDays}日以上のデータが必要です。`,
        dataCollectionDaysBefore,
        dataCollectionDaysAfter
      };
    }
  
    const beforeAvgSatisfaction =
      input.beforeAlgorithmDataSet.length > 0
        ? input.beforeAlgorithmDataSet.reduce((sum, d) => sum + d.satisfactionScore, 0) /
          input.beforeAlgorithmDataSet.length
        : 0;
  
    const afterAvgSatisfaction =
      input.afterAlgorithmDataSet.length > 0
        ? input.afterAlgorithmDataSet.reduce((sum, d) => sum + d.satisfactionScore, 0) /
          input.afterAlgorithmDataSet.length
        : 0;
  
    const beforeAvgCompletionRate =
      input.beforeAlgorithmDataSet.length > 0
        ? input.beforeAlgorithmDataSet.reduce((sum, d) => sum + d.completionRate, 0) /
          input.beforeAlgorithmDataSet.length
        : 0;
  
    const afterAvgCompletionRate =
      input.afterAlgorithmDataSet.length > 0
        ? input.afterAlgorithmDataSet.reduce((sum, d) => sum + d.completionRate, 0) /
          input.afterAlgorithmDataSet.length
        : 0;
  
    const beforeAvgCookingTime =
      input.beforeAlgorithmDataSet.length > 0
        ? input.beforeAlgorithmDataSet.reduce((sum, d) => sum + d.cookingTimeMinutes, 0) /
          input.beforeAlgorithmDataSet.length
        : 0;
  
    const afterAvgCookingTime =
      input.afterAlgorithmDataSet.length > 0
        ? input.afterAlgorithmDataSet.reduce((sum, d) => sum + d.cookingTimeMinutes, 0) /
          input.afterAlgorithmDataSet.length
        : 0;
  
    const aggregatedComparison = {
      pre_improvement_success_count: input.beforeAlgorithmDataSet.length,
      pre_improvement_success_rate: beforeAvgCompletionRate,
      post_improvement_success_count: input.afterAlgorithmDataSet.length,
      post_improvement_success_rate: afterAvgCompletionRate,
      improvement_rate_difference: afterAvgCompletionRate - beforeAvgCompletionRate,
      improvement_success_count_difference:
        input.afterAlgorithmDataSet.length - input.beforeAlgorithmDataSet.length,
      improvement_multiplier:
        beforeAvgCompletionRate > 0
          ? afterAvgCompletionRate / beforeAvgCompletionRate
          : 1,
      aggregated_at: new Date().toISOString(),
      satisfactionScoreImprovement: afterAvgSatisfaction - beforeAvgSatisfaction,
      cookingTimeReduction: beforeAvgCookingTime - afterAvgCookingTime
    };
  
    return {
      isAggregatable: true,
      aggregatedComparison,
      dataCollectionDaysBefore,
      dataCollectionDaysAfter
    };
  }
  return { compareAlgorithmImprovementQuantitatively };
})();
