    const nutritionComplianceOverallScore = (calorieComplianceScore + proteinComplianceScore + fatComplianceScore + carbohydrateComplianceScore) / 4;
  
    // 総合評価スコア計算
    const overallValidityScore = (restrictionComplianceScore + preferenceAlignmentScore + nutritionComplianceOverallScore) / 3;
  
    // 妥当性判定
    const isValid = !hasAllergyViolation && !hasReligiousViolation && !hasDietaryViolation && calorieInRange && proteinInRange && fatInRange && carbohydrateInRange;
    const validityJudgment = isValid ? "妥当" : "不妥当";
  
    // 記録日時（固定値）
