/* AIVIC_FUNCTION_BUNDLE_START owner=validateMealPlanIntegrity exports=validateMealPlanIntegrity */
const __aivicBundle_26_validateMealPlanIntegrity = (() => {
  function validateMealPlanIntegrity(input: MealPlanIntegrityCheckInput): MealPlanIntegrityResult {
    // Validate mealName
    if (!input.mealName || input.mealName.trim() === '') {
      throw new Error('料理名は必須です');
    }
  
    // Validate nutritionInfo exists
    if (!input.nutritionInfo) {
      throw new Error('栄養価情報は必須です');
    }
  
    // Validate nutritionInfo has all required fields
    if (
      input.nutritionInfo.calories === null ||
      input.nutritionInfo.calories === undefined ||
      input.nutritionInfo.protein === null ||
      input.nutritionInfo.protein === undefined ||
      input.nutritionInfo.carbs === null ||
      input.nutritionInfo.carbs === undefined ||
      input.nutritionInfo.fat === null ||
      input.nutritionInfo.fat === undefined
    ) {
      throw new Error('栄養素情報が不完全です');
    }
  
    // Validate cookingTimeMinutes
    if (input.cookingTimeMinutes === undefined || input.cookingTimeMinutes === null) {
      throw new Error('調理時間は必須です');
    }
  
    if (input.cookingTimeMinutes < 0) {
      throw new Error('調理時間は負の値にできません');
    }
  
    // Validate familyMemberId
    if (!input.familyMemberId || input.familyMemberId.trim() === '') {
      throw new Error('家族成員IDは必須です');
    }
  
    // All validations passed
    const validationTimestamp = new Date().toISOString();
  
    return {
      isValid: true,
      validationTimestamp,
      mealName: input.mealName,
      nutritionCheck: true,
      allergyCompliance: input.allergyCheckResult,
      dietaryRestrictionCompliance: input.dietaryRestrictionCheckResult,
      cookingTimeWithinLimit: input.cookingTimeMinutes >= 0,
    };
  }
  return { validateMealPlanIntegrity };
})();
