/* AIVIC_FUNCTION_BUNDLE_START owner=validateAlgorithmVersionDeployment exports=validateAlgorithmVersionDeployment */
const __aivicBundle_29_validateAlgorithmVersionDeployment = (() => {
  function validateAlgorithmVersionDeployment(
    input: RuleSpecificationDeploymentInput
  ): RuleSpecificationDeploymentResult {
    const { algorithmVersionId, verificationStartDate, verificationEndDate, targetUserSegments } = input;
  
    // Validate verificationStartDate
    if (!verificationStartDate || verificationStartDate === "") {
      throw new Error("検証期間の開始日時が無効です");
    }
    if (verificationStartDate === null) {
      throw new Error("検証期間の開始日時が無効です");
    }
  
    const startDate = new Date(verificationStartDate as string);
    if (isNaN(startDate.getTime())) {
      throw new Error("検証期間の開始日時が無効です");
    }
  
    // Validate verificationEndDate
    if (!verificationEndDate || verificationEndDate === "") {
      throw new Error("検証期間の終了日時が無効です");
    }
    if (verificationEndDate === null) {
      throw new Error("検証期間の終了日時が無効です");
    }
  
    const endDate = new Date(verificationEndDate as string);
    if (isNaN(endDate.getTime())) {
      throw new Error("検証期間の終了日時が無効です");
    }
  
    // Validate that startDate < endDate
    if (startDate >= endDate) {
      throw new Error("検証期間の開始日時は終了日時より前である必要があります");
    }
  
    // Return valid result
    return {
      isValid: true,
      algorithmVersionId,
      verificationStartDate: verificationStartDate as string,
      verificationEndDate: verificationEndDate as string,
      targetUserSegments,
      deploymentStatus: "pending",
    };
  }
  return { validateAlgorithmVersionDeployment };
})();
