/* AIVIC_FUNCTION_BUNDLE_START owner=validateAndApplySalesPeriodRule exports=validateAndApplySalesPeriodRule */
const __aivicBundle_33_validateAndApplySalesPeriodRule = (() => {
  function validateAndApplySalesPeriodRule(
    mealData: any,
    salesPeriodRule: any
  ): any {
    const queryDate = mealData.query_date;
    const salesPeriodStart = salesPeriodRule.sales_period_start;
    const salesPeriodEnd = salesPeriodRule.sales_period_end;
  
    const isWithinSalesPeriod =
      queryDate >= salesPeriodStart && queryDate <= salesPeriodEnd;
  
    const appliedDiscountRate = isWithinSalesPeriod
      ? salesPeriodRule.discount_rate
      : 0;
  
    const seasonPatternApplied = isWithinSalesPeriod
      ? salesPeriodRule.season_pattern
      : null;
  
    const ingredients = mealData.ingredients || [];
    const adjustedIngredientPrice =
      ingredients.length > 0
        ? ingredients[0].base_price *
          (1 - appliedDiscountRate / 100)
        : 0;
  
    const ruleSpecification = {
      promotion_id: salesPeriodRule.promotion_id,
      season_pattern: salesPeriodRule.season_pattern,
      discount_rate: salesPeriodRule.discount_rate,
      sales_period_start: salesPeriodStart.toISOString(),
      sales_period_end: salesPeriodEnd.toISOString(),
    };
  
    return {
      applied_discount_rate: appliedDiscountRate,
      season_pattern_applied: seasonPatternApplied,
      is_within_sales_period: isWithinSalesPeriod,
      adjusted_ingredient_price: adjustedIngredientPrice,
      rule_specification: ruleSpecification,
      is_valid_rule: true,
    };
  }
  return { validateAndApplySalesPeriodRule };
})();
