const __aivicBundle_35_integrateSeasonalPatternAndDiscountRules = (() => {
  function integrateSeasonalPatternAndDiscountRules(
    ingredientInput: {
      ingredientId: string;
      ingredientName: string;
      seasonalPattern: string;
      discountRate: number;
      salePeriodStartDate: string;
      salePeriodEndDate: string;
    },
    priorityRuleConfig: {
      priorityOrder: string[];
      seasonalPatternWeight: number;
      discountRateWeight: number;
      salePeriodWeight: number;
    }
  ): {
    ingredientId: string;
    ingredientName: string;
    seasonalPattern: string;
    discountRate: number;
    salePeriodStartDate: string;
    salePeriodEndDate: string;
    isValidSalePeriod: boolean;
    priorityScore: number;
    canBeIncludedInMenu: boolean;
    generationLogStatus: string;
    sameDatePeriodFlag: boolean;
  } {
    const startDate = new Date(ingredientInput.salePeriodStartDate);
    const endDate = new Date(ingredientInput.salePeriodEndDate);
    
    const isValidSalePeriod = startDate <= endDate;
    const sameDatePeriodFlag = ingredientInput.salePeriodStartDate === ingredientInput.salePeriodEndDate;
    
    let priorityScore = 0;
    
    if (priorityRuleConfig.priorityOrder.includes("seasonalPattern")) {
      priorityScore += ingredientInput.seasonalPattern ? priorityRuleConfig.seasonalPatternWeight * 100 : 0;
    }
    
    if (priorityRuleConfig.priorityOrder.includes("discountRate")) {
      priorityScore += (ingredientInput.discountRate / 100) * priorityRuleConfig.discountRateWeight * 100;
    }
    
    if (priorityRuleConfig.priorityOrder.includes("salePeriod")) {
      priorityScore += isValidSalePeriod ? priorityRuleConfig.salePeriodWeight * 100 : 0;
    }
    
    priorityScore = Math.round(priorityScore);
    priorityScore = Math.max(0, Math.min(100, priorityScore));
    
    const canBeIncludedInMenu = isValidSalePeriod && ingredientInput.discountRate > 0;
    const generationLogStatus = isValidSalePeriod ? "processed_successfully" : "failed";
    
    return {
      ingredientId: ingredientInput.ingredientId,
      ingredientName: ingredientInput.ingredientName,
      seasonalPattern: ingredientInput.seasonalPattern,
      discountRate: ingredientInput.discountRate,
      salePeriodStartDate: ingredientInput.salePeriodStartDate,
      salePeriodEndDate: ingredientInput.salePeriodEndDate,
      isValidSalePeriod,
      priorityScore,
      canBeIncludedInMenu,
      generationLogStatus,
      sameDatePeriodFlag,
    };
  }
  return { integrateSeasonalPatternAndDiscountRules };
})();
