    const isPreparationCompleted = allItemsCompleted && timeUntilMeetingMinutes <= 0;
    const allItemsReady = allItemsCompleted && timeUntilMeetingMinutes <= 0;
  
    const notificationsSent: string[] = [];
    if (isPreparationCompleted && timeUntilMeetingMinutes === 0) {
      notificationsSent.push('preparation_completed');
      notificationsSent.push('meeting_start_soon');
    }
  
    const secondPrecisionAccuracy = currentTime.getMilliseconds() === 0;
  
    const activatedAt = isPreparationCompleted ? meetingScheduledDate : undefined;
  
    return {
      isPreparationCompleted,
      preparationStatus,
      allItemsReady,
      activatedAt,
      timeUntilMeeting: timeUntilMeetingMinutes,
      notificationsSent,
      secondPrecisionAccuracy,
      preparationItems,
    };
