/* AIVIC_FUNCTION_BUNDLE_START owner=validateQualityGate exports=validateQualityGate */
const __aivicBundle_54_validateQualityGate = (() => {
  function validateQualityGate(input: any): any {
    // ケース1: improvement_id, metric_value, pass_threshold を持つシンプルな改善案
    if (
      input.improvement_id !== undefined &&
      input.metric_value !== undefined &&
      input.pass_threshold !== undefined
    ) {
      // 入力値の検証
      if (input.improvement_id === "") {
        throw new Error("改善IDが空です");
      }
      if (input.metric_value < 0) {
        throw new Error("メトリクス値が負の値です");
      }
      if (input.pass_threshold < 0) {
        throw new Error("閾値が負の値です");
      }
  
      const passed = input.metric_value >= input.pass_threshold;
      return {
        improvement_id: input.improvement_id,
        passed: passed,
        metric_value: input.metric_value,
        threshold: input.pass_threshold,
        reason: passed ? "合格" : "不合格",
      };
    }
  
    // ケース2: proposalId, algorithmVersion, testCoverage, performanceScore, successRate を持つ改善案
    if (
      input.proposalId !== undefined &&
      input.algorithmVersion !== undefined &&
      input.testCoverage !== undefined &&
      input.performanceScore !== undefined &&
      input.successRate !== undefined
    ) {
      const requiredTestCoverage = 80;
      const requiredPerformanceScore = 75;
      const requiredSuccessRate = 85;
  
      const failureDetails: Array<{
        metricName: string;
        requiredValue: number;
        actualValue: number;
      }> = [];
  
      if (input.testCoverage < requiredTestCoverage) {
        failureDetails.push({
          metricName: "testCoverage",
          requiredValue: requiredTestCoverage,
          actualValue: input.testCoverage,
        });
      }
  
      if (input.performanceScore < requiredPerformanceScore) {
        failureDetails.push({
          metricName: "performanceScore",
          requiredValue: requiredPerformanceScore,
          actualValue: input.performanceScore,
        });
      }
  
      const deploymentApproved =
        input.testCoverage >= requiredTestCoverage &&
        input.performanceScore >= requiredPerformanceScore &&
        input.successRate >= requiredSuccessRate;
  
      return {
        deploymentApproved: deploymentApproved,
        status: deploymentApproved ? "PASSED" : "FAILED",
        failureDetails: failureDetails,
      };
    }
  
    return {};
  }
  return { validateQualityGate };
})();
export const validateQualityGate = __aivicBundle_54_validateQualityGate.validateQualityGate;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateQualityGate */

