/* AIVIC_FUNCTION_BUNDLE_START owner=validateMeetingParticipantAttendance exports=validateMeetingParticipantAttendance */
const __aivicBundle_56_validateMeetingParticipantAttendance = (() => {
  interface ValidateMeetingParticipantAttendanceInput {
    meetingId: string;
    scheduledTime: Date;
    currentTime: Date;
    participants: Array<{
      participantId: string;
      name: string;
      attendanceStatus: string;
      delegateId: string | null;
      delegateName: string | null;
    }>;
  }
  
  interface ValidateMeetingParticipantAttendanceOutput {
    meetingId: string;
    requiresPostponementJudgment: boolean;
    absentParticipantCount: number;
    assignedDelegateCount: number;
    postponementJudgmentPossible?: boolean;
    statusUpdates: Array<{
      participantId: string;
      newStatus: string;
      delegateId?: string;
    }>;
    errorMessage?: string;
    unassignedAbsentParticipants?: string[];
    onlyDelegateAssignmentApplied?: boolean;
    success?: boolean;
  }
  
   function validateMeetingParticipantAttendance(
    input: ValidateMeetingParticipantAttendanceInput
  ): ValidateMeetingParticipantAttendanceOutput {
    const {
      meetingId,
      scheduledTime,
      currentTime,
      participants,
    } = input;
  
    const timeUntilMeeting = scheduledTime.getTime() - currentTime.getTime();
    const hoursUntilMeeting = timeUntilMeeting / (1000 * 60 * 60);
    const isWithin24h = hoursUntilMeeting <= 24;
  
    const absentParticipants = participants.filter(
      (p) => p.attendanceStatus === 'absent'
    );
    const absentParticipantCount = absentParticipants.length;
  
    const assignedDelegates = absentParticipants.filter(
      (p) => p.delegateId !== null && p.delegateId !== undefined
    );
    const assignedDelegateCount = assignedDelegates.length;
  
    const unassignedAbsent = absentParticipants.filter(
      (p) => p.delegateId === null || p.delegateId === undefined
    );
    const unassignedAbsentParticipants = unassignedAbsent.map(
      (p) => p.participantId
    );
  
    const statusUpdates = assignedDelegates.map((p) => ({
      participantId: p.participantId,
      newStatus: 'absent_with_delegate',
      delegateId: p.delegateId!,
    }));
  
    const hasUnassignedAbsent = unassignedAbsentParticipants.length > 0;
  
    if (isWithin24h) {
      const requiresPostponementJudgment = absentParticipantCount > 0;
      const postponementJudgmentPossible = !hasUnassignedAbsent;
  
      const result: ValidateMeetingParticipantAttendanceOutput = {
        meetingId,
        requiresPostponementJudgment,
        absentParticipantCount,
        assignedDelegateCount,
        postponementJudgmentPossible,
        statusUpdates,
      };
  
      if (hasUnassignedAbsent) {
        result.errorMessage = `代理者未指定の不在者がいます: ${unassignedAbsentParticipants.join(', ')}`;
        result.unassignedAbsentParticipants = unassignedAbsentParticipants;
      }
  
      if (absentParticipantCount === 0) {
        result.success = true;
      }
  
      return result;
    } else {
      if (hasUnassignedAbsent) {
        return {
          meetingId,
          requiresPostponementJudgment: false,
          absentParticipantCount,
          assignedDelegateCount,
          statusUpdates: [],
          success: false,
          errorMessage: `代理者未指定の不在者がいます: ${unassignedAbsentParticipants.join(', ')}`,
          unassignedAbsentParticipants,
        };
      }
  
      return {
        meetingId,
        requiresPostponementJudgment: false,
        absentParticipantCount,
        assignedDelegateCount,
        onlyDelegateAssignmentApplied: absentParticipantCount > 0,
        statusUpdates,
      };
    }
  }
  return { validateMeetingParticipantAttendance };
})();
export const validateMeetingParticipantAttendance = __aivicBundle_56_validateMeetingParticipantAttendance.validateMeetingParticipantAttendance;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateMeetingParticipantAttendance */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateMeetingParticipants exports=validateMeetingParticipants */
const __aivicBundle_57_validateMeetingParticipants = (() => {
  function validateMeetingParticipants(input: {
    meeting_id: string;
    scheduled_participants: Array<{
      participant_id: string;
      participant_name: string;
      attendance_status: string;
      substitute_id: string | null;
    }>;
    minimum_required_participants: number;
  }): {
    actual_attendees_count: number;
    effective_attendees_count: number;
    meeting_status: string;
    is_valid: boolean;
    absent_without_substitute: Array<{
      participant_id: string;
      participant_name: string;
    }>;
  } {
    const { meeting_id, scheduled_participants, minimum_required_participants } = input;
  
    const actual_attendees_count = scheduled_participants.filter(
      (p) => p.attendance_status === "attended"
    ).length;
  
    const absent_with_substitute = scheduled_participants.filter(
      (p) => p.attendance_status === "absent" && p.substitute_id !== null
    ).length;
  
    const effective_attendees_count = actual_attendees_count + absent_with_substitute;
  
    const absent_without_substitute = scheduled_participants
      .filter((p) => p.attendance_status === "absent" && p.substitute_id === null)
      .map((p) => ({
        participant_id: p.participant_id,
        participant_name: p.participant_name,
      }));
  
    const is_valid = effective_attendees_count >= minimum_required_participants;
  
    const meeting_status = is_valid ? "can_proceed" : "cannot_proceed";
  
    return {
      actual_attendees_count,
      effective_attendees_count,
      meeting_status,
      is_valid,
      absent_without_substitute,
    };
  }
  return { validateMeetingParticipants };
})();
